function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var OPS={held:['Claims skeptic','Prove each claim against the record','Re-read the transcript behind every quote.','held','Quotes stand.'],changed:['Sanity check','Does the first screen answer the job?','It did not.','changed','Next move is now the first row.'],broke:['Chief loki','Summary lines must match their bodies','Counted every fold.','broke','The hint said 9 folds; there are 10.']};
function kitPass(k){var p=OPS[k];return '<div class="pass"><div><span class="pass-k">'+kEsc(p[0])+'</span><p>'+kEsc(p[1])+'</p></div><div><span class="pass-k">Found</span><p>'+kEsc(p[2])+'</p></div><div><span class="pass-k">Ruling</span><p><span class="pass-v '+p[3]+'">'+p[3]+'</span>'+kEsc(p[4])+'</p></div></div>'}
function kitPasses(host,ks){var w=document.createElement('div');w.className='passes';w.innerHTML=ks.map(kitPass).join('');host.appendChild(w);return w}
kitPasses(kSlot(),['held','changed','broke']);
STATES.forEach(function(a,i){var b=document.createElement('div');b.style.maxWidth=a[1];kSlot(i).appendChild(b);kitPasses(b,a[0])});
